const raw = String($json.output ?? '').trim();
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
const jsonText = start >= 0 && end >= start ? raw.slice(start, end + 1) : raw;
let value;
try { value = JSON.parse(jsonText); } catch { value = { responseType: 'ERROR', message: 'The assistant returned an invalid response. Please try again.', requiresConfirmation: false }; }
const allowedTypes = ['ANSWER','CLARIFICATION','CART_PROPOSAL','NO_MATCH','REFUSAL','ERROR'];
if (!allowedTypes.includes(value.responseType)) value.responseType = 'ERROR';
value.correlationId = $('Normalize Agent Request').first().json.correlationId;
value.message = String(value.message || 'The request could not be completed.').slice(0, 800);
value.candidates = Array.isArray(value.candidates) ? value.candidates.slice(0, 12).map(c => ({ productId: c.productId || c.product?.productId, name: c.name || c.product?.name || 'Product', similarityScore: c.similarityScore ?? null, quantity: Number.isInteger(Number(c.quantity)) && Number(c.quantity) > 0 ? Number(c.quantity) : 1, quantity: Number.isInteger(Number(c.quantity)) && Number(c.quantity) > 0 ? Number(c.quantity) : 1 })).filter(c => /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(String(c.productId || ''))) : [];
if (value.responseType === 'CART_PROPOSAL') {
  const input = value.proposal || {};
  const rawItems = Array.isArray(input.items) ? input.items : (input.productId || input.product?.productId) ? [{ productId: input.productId || input.product.productId, name: input.name || input.product?.name || 'Product', quantity: input.quantity }] : [];
  const items = rawItems.slice(0, 20).map(item => ({ productId: item.productId, name: String(item.name || 'Product').slice(0,120), quantity: Number(item.quantity) }));
  const valid = items.length > 0 && items.every(item => /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(String(item.productId || '')) && Number.isInteger(item.quantity) && item.quantity >= 1 && item.quantity <= 9999) && new Set(items.map(item => item.productId)).size === items.length;
  if (!valid) {
    value = { responseType: 'ERROR', message: 'A valid proposal could not be created.', requiresConfirmation: false, correlationId: value.correlationId, proposal: null, candidates: value.candidates };
  } else {
    value.proposal = { action: 'ADD_ITEMS', items };
    value.requiresConfirmation = true;
  }
} else {
  value.requiresConfirmation = false;
  value.proposal = null;
}
return [{ json: value }];
